// Family Living Expense: parse OpenAI JSON, map payment -> Paid By, sheet tab MM-MMM, Drive filename
const openAiResponse = $input.first().json;
let parsed;

try {
  const content = openAiResponse.content || openAiResponse.text || JSON.stringify(openAiResponse);
  const jsonMatch = content.match(/```(?:json)?\n?([\s\S]*?)\n?```/) || [null, content];
  parsed = JSON.parse(jsonMatch[1].trim());
} catch (e) {
  throw new Error(`Failed to parse OpenAI response: ${e.message}`);
}

const PAYMENT_TO_PERSON = {
  "AMEX Marriott Bonvoy - 0771": "Eki",
  "AMEX Marriott Bonvoy - 2593": "Eki",
  "AMEX Marriott Bonvoy - 2018": "Eki",
  "AMEX Marriott Bonvoy - 1002": "Eki",
  "BMO Business Debit - 1705": "Kevard",
  "BMO Debit - 7035": "Kevard",
  "BMO Post-dated Cheque": "Kevard",
  "Cash": "Eki",
  "CIBC Costco Mastercard - 5140": "Kevard",
  "CIBC Costco Mastercard - 0486": "Kevard",
  "CIBC Debit": "Eki",
  "CIBC Pre-Authorized": "Eki",
  "HSBC World Debit - 7418": "Kevard",
  "HSBC World Debit - 7698": "Kevard",
  "HSBC World Debit - 8955": "Eki",
  "HSBC World Debit - 6315": "Eki",
  "Interac": "Eki",
  "NEO World Elite Mastercard - 5002": "Kevard",
  "NEO World Elite Mastercard - 2033": "Kevard",
  "PC Optimum Mastercard - 7107": "Kevard",
  "PC Optimum Mastercard - 5520": "Kevard",
  "RBC Cashback Mastercard - 4894": "Eki",
  "RBC Cashback Mastercard - 0154": "Eki",
  "RBC Debit": "Eki",
  "Rogers Business Mastercard - 8887": "Kevard",
  "Rogers Business Mastercard - 3072": "Kevard",
  "Scotia Visa - 8548": "Kevard",
  "Triangle Mastercard - 2562": "Kevard"
};

const ALLOWED_CATEGORIES = new Set(["Amazon", "Body Care", "Car", "Clothes & Shoes", "Dental", "Drink", "Electricity & Water", "Entertainment", "Food", "Gardening", "Gas", "Gift", "Grocery", "Health", "House Moving", "House Rent", "IKEA", "Insurance", "Internet", "Medicine", "Membership", "Miscellaneous", "Mobile", "Penalty", "Pet", "PR", "Refund", "Sports", "Tax", "Tools", "Transport", "Travel", "Wedding"]);

function normalizeCategory(c) {
  if (c && ALLOWED_CATEGORIES.has(c)) return c;
  return 'Miscellaneous';
}

const details = (parsed.items || [])
  .map((item) => {
    const qty = item.quantity && item.quantity > 1 ? `${item.quantity}x ` : '';
    const desc = item.description || '';
    const amt = item.amount != null && item.amount !== '' ? ` (${item.amount})` : '';
    return `${qty}${desc}${amt}`;
  })
  .filter(Boolean)
  .join('; ');

const iso = parsed.date || new Date().toISOString().split('T')[0];
const parts = iso.split('-');
const y = parts[0] || String(new Date().getFullYear());
const m = parts[1] || '01';
const dayRaw = parts[2] || '01';
const day = String(parseInt(dayRaw, 10)).padStart(2, '0');

const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const mmm = monthNames[Math.max(0, Math.min(11, parseInt(m, 10) - 1))];
const mm = String(Math.max(1, Math.min(12, parseInt(m, 10)))).padStart(2, '0');
const sheetName = `${mm}-${mmm}`;

let amountCad = Number(parsed.total);
if (Number.isNaN(amountCad)) amountCad = 0;
const cur = (parsed.currency || 'CAD').toUpperCase();
const remarkParts = [];
if (parsed.remarks) remarkParts.push(String(parsed.remarks).trim());

if (cur !== 'CAD') {
  remarkParts.push(`Non-CAD receipt (${cur}); verify Amount (CAD).`);
}

const pm = parsed.payment_method != null ? String(parsed.payment_method).trim() : '';
let paidBy = pm && PAYMENT_TO_PERSON[pm] ? PAYMENT_TO_PERSON[pm] : '';
if (pm && !paidBy) {
  remarkParts.push(`Unknown payment_method "${pm}" — set Paid By manually.`);
}

const category = normalizeCategory(parsed.category);
const vendor = (parsed.vendor_name || 'receipt').replace(/[^\w\s-]/g, '').replace(/\s+/g, ' ').trim().slice(0, 80) || 'receipt';
const driveFilename = `Living Expense ${y} - ${iso} - ${vendor.replace(/\s/g, '_')}.jpg`;

const submittedAt = new Date().toISOString();

return [
  {
    json: {
      sheetName,
      sheetData: {
        day,
        category,
        details,
        paidBy,
        paymentMethod: pm,
        amountCad,
        remarks: remarkParts.filter(Boolean).join(' ').trim(),
        submittedAt,
      },
      driveFilename,
      extractedData: {
        vendor: parsed.vendor_name,
        date: iso,
        day,
        sheetName,
        category,
        details,
        paidBy,
        paymentMethod: pm,
        amountCad,
        currency: cur,
        remarks: remarkParts.join(' ').trim(),
        items: parsed.items || [],
        confidence: parsed.confidence,
        submittedAt,
      },
    },
  },
];

// Merge Google Drive link into the response
const formatData = $('Format Data').first().json;
const driveResult = $('Google Drive - Upload Image').first().json;
const sheetsResult = $('Google Sheets - Append Row').first().json;

const driveLink = driveResult.webViewLink || driveResult.webContentLink || '';

return [
  {
    json: {
      success: true,
      data: {
        ...formatData.extractedData,
        driveLink: driveLink,
        sheetRow: sheetsResult.updates?.updatedRows || null
      }
    }
  }
];
